import React, { useState } from 'react'
import { InputNumber } from 'primereact/inputnumber';

export default function Buttons() {
    const [value1, setValue1] = useState(20);
    const [value2, setValue2] = useState(10.50);
    const [value3, setValue3] = useState(25);

    return (
        <div className="fxb fvc gp3 wrap">
            <div>
                <label htmlFor="stacked-buttons" className="bold-font block mgb2 font-size14">Stacked</label>
                <InputNumber 
                    buttonLayout="stacked" 
                    inputId="stacked-buttons" 
                    value={value1} 
                    onValueChange={(e) => setValue1(e.value)} 
                    showButtons 
                    mode="currency" 
                    currency="USD" />
            </div>

            <div>
                <label htmlFor="minmax-buttons" className="bold-font block mgb2 font-size14">Min-Max Boundaries</label>
                <InputNumber 
                    buttonLayout="stacked" 
                    inputId="minmax-buttons" 
                    value={value3} 
                    onValueChange={(e) => setValue3(e.value)} 
                    mode="decimal" 
                    showButtons 
                    min={0} 
                    max={100} 
                />
            </div>
            <div>
                <label htmlFor="horizontal-buttons" className="bold-font block mgb2 font-size14">Horizontal with Step</label>
                <InputNumber 
                    buttonLayout="horizontal" 
                    inputId="horizontal-buttons" 
                    value={value2} 
                    onValueChange={(e) => setValue2(e.value)} 
                    showButtons 
                    step={0.25}
                    decrementButtonClassName="danger" 
                    incrementButtonClassName="success" 
                    incrementButtonIcon="pi pi-plus" 
                    decrementButtonIcon="pi pi-minus"
                    mode="currency" currency="EUR" />
            </div>
        </div>
    )
}
